#include "firmware/core/state_machine.hpp"
namespace rail { ErrorCode AcquisitionStateMachine::dispatch(AcquisitionEvent e){switch(state_){case AcquisitionState::Idle:if(e==AcquisitionEvent::Start){state_=AcquisitionState::Starting;return ErrorCode::Ok;}break;case AcquisitionState::Starting:if(e==AcquisitionEvent::Started){state_=AcquisitionState::Recording;return ErrorCode::Ok;}break;case AcquisitionState::Recording:if(e==AcquisitionEvent::Stop){state_=AcquisitionState::Stopping;return ErrorCode::Ok;}if(e==AcquisitionEvent::Fault){state_=AcquisitionState::Fault;return ErrorCode::Ok;}break;case AcquisitionState::Stopping:if(e==AcquisitionEvent::Stopped){state_=AcquisitionState::Idle;return ErrorCode::Ok;}break;case AcquisitionState::Fault:if(e==AcquisitionEvent::Reset){state_=AcquisitionState::Idle;return ErrorCode::Ok;}break;}return ErrorCode::InvalidState;}
PowerAction PowerStateMachine::dispatch(PowerEvent e){if(e==PowerEvent::ExternalLost)return PowerAction::StopAcquisition;if(e==PowerEvent::DataFlushed){shutdown_requested_=true;return PowerAction::RequestShutdown;}if(e==PowerEvent::OsShutdownComplete&&shutdown_requested_)return PowerAction::CutPower;if(e==PowerEvent::Timeout)return PowerAction::Fault;return PowerAction::None;}
}
